<script setup lang="ts">import {onMounted,ref} from 'vue';import http from '../api/http';import PublicState from './PublicState.vue';const loading=ref(true),error=ref(''),hospital=ref<any>(null),campuses=ref<any[]>([]),departments=ref<any[]>([]),doctors=ref<any[]>([]);onMounted(async()=>{try{const [h,c,d,x]=await Promise.all([http.get('/public/hospital'),http.get('/public/campuses'),http.get('/public/departments'),http.get('/public/doctors',{params:{page:1,pageSize:6}})]);hospital.value=h.data.data;campuses.value=c.data.data;departments.value=d.data.data;doctors.value=x.data.data.records;}catch(e:any){error.value=e.message??'无法加载医院信息';}finally{loading.value=false;}});</script><template><PublicState :loading="loading" :error="error" :empty="!hospital"><section class="hero"><p>HOSPITAL MASTER DATA</p><h1>{{hospital.name}}</h1><p>{{hospital.introduction||'为患者提供清晰、可信的医院主数据信息。'}}</p><div>{{hospital.serviceHotline||hospital.telephone||'服务电话暂未公布'}}</div></section><section><h2>院区导航</h2><div class="cards"><router-link v-for="campus in campuses" :key="campus.id" to="/campuses" class="card"><h3>{{campus.name}}</h3><p>{{campus.address||'地址信息待完善'}}</p></router-link></div></section><section><div class="title"><h2>科室服务</h2><router-link to="/departments">查看全部</router-link></div><div class="cards"><router-link v-for="department in departments.slice(0,6)" :key="department.id" :to="`/departments/${department.id}`" class="card"><h3>{{department.name}}</h3><p>{{department.introduction||'了解科室服务与位置'}}</p></router-link></div></section><section><div class="title"><h2>医生团队</h2><router-link to="/doctors">查看全部</router-link></div><div class="cards"><router-link v-for="doctor in doctors" :key="doctor.id" :to="`/doctors/${doctor.id}`" class="card"><h3>{{doctor.name}}</h3><p>{{doctor.title||'职称待完善'}}</p><p>{{doctor.specialtySummary||doctor.profile||'医生公开简介待完善'}}</p></router-link></div></section></PublicState></template>
